    # Split the figure into maximal rectangles based on row spans. Use key palette
    # in the repeated order seen in examples: blocks along the path are 2,4,3,4,1.
    if h<20:
        for i,j in cells:
            if i<=6: c=2
            elif i<=10: c=4
            elif i<=14: c=3
            else: c=1
            out[i][j]=c
    else:
        for i,j in cells:
            if i<=12: c=2 if j<4 else 4
            elif i<=15: c=3
            elif i<=18: c=4 if j<4 else 1
            out[i][j]=c
    for i in range(h):
        for j in range(w):
            if grid[i][j] not in (0,8): out[i][j]=0
    return out
